begin;
select plan(24);
select has_table('public','together_user_personas','Personas are canonical in-world user identities');
select has_table('public','together_continuities','Kivelle Lives have an explicit isolation boundary');
select has_table('public','together_continuity_world_state','World progression can remain Life-specific');
select has_column('public','together_profiles','active_continuity_id','Account preference points to the active Life');
select has_column('public','together_character_instances','continuity_id','Character instances belong to a Life');
select has_column('public','together_memories','continuity_id','Memories expose their Life boundary');
select has_column('public','together_shared_plans','continuity_id','Plans expose their Life boundary');
select has_column('public','together_date_sessions','continuity_id','Dates expose their Life boundary');
select has_column('public','together_moments','continuity_id','Moments expose their Life boundary');
select has_column('public','together_story_arc_instances','continuity_id','Stories expose their Life boundary');
select has_column('public','together_generated_media','continuity_id','Generated media exposes its Life boundary');
select has_column('public','together_character_templates','public_handle','Custom characters have stable unique handles');
select has_column('public','together_character_templates','lifecycle_status','Custom character lifecycle is canonical');
select has_column('public','together_character_templates','visibility','Private creation is explicit');
select has_column('public','together_character_templates','relationship_goal','Connection intent is content-owned');
select has_column('public','together_character_versions','relationship_config','Relationship behavior belongs to a version');
select has_column('public','together_character_versions','life_config','Generated life configuration belongs to a version');
select has_column('public','together_character_versions','appearance_candidates','Explicit appearance generation is persisted');
select trigger_is('public','together_character_instances','together_character_instance_continuity_owner','public','kivelle_validate_continuity_owner','Instances cannot cross account ownership');
select trigger_is('public','together_memories','together_memories_fill_continuity','public','kivelle_fill_state_continuity','Memory continuity derives from its companion instance');
select trigger_is('public','together_shared_plans','together_shared_plans_fill_continuity','public','kivelle_fill_state_continuity','Plan continuity derives from its companion instance');
select ok((select relrowsecurity from pg_class where oid='public.together_user_personas'::regclass),'Personas use RLS');
select ok((select relrowsecurity from pg_class where oid='public.together_continuities'::regclass),'Continuities use RLS');
select ok(not exists(select 1 from pg_constraint where conrelid='public.together_character_templates'::regclass and contype='u' and pg_get_constraintdef(oid)='UNIQUE (name)'),'Custom display names are not globally unique');
select * from finish();
rollback;
